create table if not exists users(id integer primary key, username text unique, password text, role text, name text);
create table if not exists customers(id integer primary key, name text, gstin text, state text, phone text, city text);
create table if not exists products(id integer primary key, name text, hsn text, gst_rate real, price real, expected_yield real, avg_cost real default 0, reorder real default 100);
create table if not exists materials(id integer primary key, name text, kind text, unit text, avg_cost real default 0, reorder real default 0);
create table if not exists bom(id integer primary key, product_id int, material_id int, qty real);
create table if not exists orders(id integer primary key, customer_id int, status text, created text, salesman text, total real default 0);
create table if not exists order_items(id integer primary key, order_id int, product_id int, qty real, price real, gst_rate real);
create table if not exists invoices(id integer primary key, number text unique, order_id int, customer_id int, date text, taxable real, cgst real, sgst real, igst real, total real);
create table if not exists payments(id integer primary key, invoice_id int, amount real, mode text, date text);
create table if not exists purchases(id integer primary key, supplier text, material_id int, qty real, rate real, batch text, expiry text, date text, gst_rate real default 5);
create table if not exists productions(id integer primary key, batch_no text, product_id int, date text, supervisor text, batches real, expected_packets real, good_packets real, damaged real, wastage real, raw_cost real, pack_cost real, labour real, gas real, power real, total_cost real, cost_per_packet real, max_variance real, status text);
create table if not exists production_materials(id integer primary key, production_id int, material_id int, planned real, actual real, variance_pct real);
create table if not exists stock_ledger(id integer primary key, ts text, item_type text, item_id int, qty real, unit_cost real, ref_type text, ref_id int, batch text, expiry text);
create table if not exists audit_log(id integer primary key, ts text, user text, action text, detail text);
